/**
 * Single source of truth for the shell completion surface of the CLI.
 *
 * The hand-rolled parser in `cli.tsx` and the static `--help` text both
 * describe the same flags; this module adds a third consumer so the bash,
 * zsh, and fish scripts generated by `render.ts` can never silently drift
 * when a flag or subcommand is added. Update THIS file and the completion
 * scripts pick it up; the other two call sites still need a matching edit.
 *
 * Note: in-app slash commands (`/clear`, `/doctor`, …) are deliberately NOT
 * here — they are typed inside the TUI and never reach the shell, so shell
 * completion cannot and should not offer them.
 */

export interface CompletionFlag {
	/** Long name without the leading dashes, e.g. `provider` for `--provider`. */
	name: string;
	/** Short name without the leading dash, e.g. `c` for `-c`. */
	short?: string;
	/** Whether the flag consumes the following token as its value. */
	takesValue: boolean;
	/** Closed set of values offered for completion, when one exists. */
	values?: readonly string[];
	/** Placeholder shown for the value in help-style listings. */
	valueName?: string;
	description: string;
}

export interface CompletionSubcommand {
	name: string;
	description: string;
	/** Nested positional tokens, e.g. `daemon` → `start|stop|…`. */
	children?: readonly string[];
}

export const COMPLETION_SHELLS = ['bash', 'zsh', 'fish'] as const;
export type CompletionShell = (typeof COMPLETION_SHELLS)[number];

